 IF EXISTS (SELECT 1 FROM (VALUES ('ad_free_slot_limit_before_insert','public.ad_free_slots','public.enforce_ad_free_slot_limit()',7),('ad_listing_identity_before_update','public.ad_listings','public.protect_ad_listing_identity()',19),('ad_free_slots_append_only','public.ad_free_slots','public.reject_ad_audit_mutation()',27),('ad_request_receipts_append_only','public.ad_request_receipts','public.reject_ad_audit_mutation()',27),('ad_moderation_events_append_only','public.ad_moderation_events','public.reject_ad_audit_mutation()',27),('media_assets_pending_mobility_document_review','public.media_assets','public.create_pending_mobility_document_review()',5),('taxi_pricing_revisions_append_only','public.taxi_pricing_revisions','public.reject_taxi_pricing_revision_mutation()',27),('billing_credit_ledger_no_rewrite','public.billing_credit_ledger','public.reject_billing_ledger_mutation()',27),('billing_usage_receipts_no_rewrite','public.billing_usage_receipts','public.reject_billing_ledger_mutation()',27),('billing_promo_redemptions_no_rewrite','public.billing_promo_redemptions','public.reject_billing_ledger_mutation()',27),('billing_welcome_after_session','public.identity_sessions','public.grant_welcome_credit_on_login()',5),('taxi_operational_approval_events_append_only','khedmah_taxi.operational_approval_events','khedmah_taxi.reject_operational_approval_event_mutation()',27)) e(name,relation,routine,kind)
